/* @lc app=leetcode id=4017 lang=kotlin */ class Solution { fun upd(bit: LongArray, i: Int, d: Long): Unit = generateSequence(i + 1) { it + (it and -it) }.takeWhile { it < bit.size }.forEach { bit[it] += d } fun qry(bit: LongArray, i: Int): Long = generateSequence(i) { it - (it and -it) }.takeWhile { it > 0 }.sumOf { bit[it] } fun sw(bit: LongArray, w: LongArray, p: Int, v: Long): Unit = upd(bit, p, v - w[p]).also { w[p] = v } fun fix(ts: java.util.TreeSet<Int>, bit: LongArray, w: LongArray, nums: IntArray, k: Int) = (k in 1..nums.size - 2 && nums[k] > nums[k - 1] && nums[k] > nums[k + 1]).let { pk -> if (pk && !ts.contains(k)) ts.add(k).also { sw(bit, w, k, ts.lower(k)?.let { (k - it).toLong() * k } ?: 0L) }.also { ts.higher(k)?.let { nx -> sw(bit, w, nx, (nx - k).toLong() * nx) } } else if (!pk && ts.contains(k)) ts.remove(k).also { sw(bit, w, k, 0L) }.also { ts.higher(k)?.let { nx -> sw(bit, w, nx, ts.lower(k)?.let { (nx - it).toLong() * nx } ?: 0L) } } else Unit } fun countOfPeaks(nums: IntArray, queries: Array<IntArray>): LongArray = nums.size.let { n -> java.util.TreeSet<Int>().let { ts -> LongArray(n + 2).let { bit -> LongArray(n + 1).let { w -> (1..n - 2).forEach { fix(ts, bit, w, nums, it) }.let { queries.mapNotNull { q -> if (q[0] == 1) q[1].let { l -> q[2].let { r -> ts.ceiling(l + 1).let { p1 -> ts.floor(r - 1).let { pt -> if (p1 == null || pt == null || p1 > pt) 0L else r.toLong() * (pt - p1) - (qry(bit, pt + 1) - qry(bit, p1 + 1)) + (p1 - l).toLong() * (r - p1) } } } } else nums.set(q[1], q[2]).let { (q[1] - 1..q[1] + 1).forEach { fix(ts, bit, w, nums, it) } }.let { null } }.toLongArray() } } } } } }